import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.Desnpdez.js";const n="/mbit-mcpo-proxy-download/guide/images/guides/ms365-readme-examples.png",i="/mbit-mcpo-proxy-download/guide/images/guides/ms365-readme-login-example.png",s="/mbit-mcpo-proxy-download/guide/images/preset-microsoft-365-guide-modal.png",l="/mbit-mcpo-proxy-download/guide/images/preset-microsoft-365-add-dialog.png",b=JSON.parse('{"title":"Microsoft 365","description":"","frontmatter":{},"headers":[],"relativePath":"presets/microsoft-365.md","filePath":"presets/microsoft-365.md"}'),d={name:"presets/microsoft-365.md"};function p(h,e,c,g,m,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="microsoft-365" tabindex="-1">Microsoft 365 <a class="header-anchor" href="#microsoft-365" aria-label="Permalink to &quot;Microsoft 365&quot;">​</a></h1><p>The <strong>Microsoft 365</strong> preset connects assistants to Microsoft Graph–based tools (mail, calendar, files, and more) using the <a href="https://github.com/Softeria/ms-365-mcp-server" target="_blank" rel="noreferrer">ms-365-mcp-server</a> project under the hood.</p><h2 id="read-the-in-app-guide-first" tabindex="-1">Read the in-app guide first <a class="header-anchor" href="#read-the-in-app-guide-first" aria-label="Permalink to &quot;Read the in-app guide first&quot;">​</a></h2><p>After adding the preset, open <strong>Integrations → Microsoft 365</strong> in the sidebar. The screenshots walk through sign-in with <strong>plain language</strong> prompts in your assistant.</p><h3 id="example-prompts-from-the-in-app-guide" tabindex="-1">Example prompts (from the in-app guide) <a class="header-anchor" href="#example-prompts-from-the-in-app-guide" aria-label="Permalink to &quot;Example prompts (from the in-app guide)&quot;">​</a></h3><p><img src="'+n+'" alt="Example chat prompts for Microsoft 365"></p><h3 id="sign-in-hint" tabindex="-1">Sign-in hint <a class="header-anchor" href="#sign-in-hint" aria-label="Permalink to &quot;Sign-in hint&quot;">​</a></h3><p><img src="'+i+'" alt="Login flow hint"></p><h2 id="before-you-add-it" tabindex="-1">Before you add it <a class="header-anchor" href="#before-you-add-it" aria-label="Permalink to &quot;Before you add it&quot;">​</a></h2><p>From the <strong>Learn more</strong> sheet in the app:</p><ul><li>Turn on <strong>Work or school</strong> when your workplace uses Teams, SharePoint, or similar. Leave it off for a personal Microsoft account.</li><li><strong>China-only</strong> tenants may need an extra cloud option—only when your administrator says so.</li></ul><p><img src="'+s+'" alt="Microsoft 365 learn more"></p><h2 id="add-connection-dialog" tabindex="-1">Add connection dialog <a class="header-anchor" href="#add-connection-dialog" aria-label="Permalink to &quot;Add connection dialog&quot;">​</a></h2><ul><li><strong>Connection name</strong> — optional friendly label.</li><li><strong>Work or school account</strong> — matches the note above.</li><li><strong>Microsoft cloud</strong> — almost always <strong>Global</strong> unless IT says otherwise.</li><li><strong>Read-only mode</strong> — safer default when you only need reads.</li><li>Optional tuning fields match the upstream server; expand <strong>Tuning &amp; credentials</strong> only when support or documentation asks.</li></ul><p><img src="'+l+'" alt="Microsoft 365 add connection"></p><h2 id="after-adding" tabindex="-1">After adding <a class="header-anchor" href="#after-adding" aria-label="Permalink to &quot;After adding&quot;">​</a></h2><ol><li>Enable the connection under <strong>My connections</strong>.</li><li>Turn the bridge <strong>on</strong> on <strong>Home</strong>.</li><li>Ask your assistant in natural language to sign in to Microsoft—the browser window handles authentication.</li></ol><p>Tokens are stored in the app data folder so logins survive restarts. Clear them under <strong><a href="./../everyday/settings.html#privacy-and-security">Settings → OAuth tokens</a></strong> if you need a fresh session.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./../everyday/open-webui.html">Open WebUI</a></strong> — if you sync tools instead of manual links.</li><li><strong><a href="./../help/troubleshooting.html">Troubleshooting</a></strong>.</li></ul>',20)])])}const y=o(d,[["render",p]]);export{b as __pageData,y as default};
